import {useLayoutEffect,useRef} from 'react';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';
import {View,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {PanelButton,Reason} from "@/components/nyc-tron/ui/components/forge/layers/panel-button";
import {CLIP_INDENT,clipReason,clipToggleLabel,type ClipLayer,type SetClippedOp} from "@/components/nyc-tron/ui/components/forge/layers/clipping-model";

/** Props for {@linkcode ClipToggle}. */
export interface ClipToggleProps extends Omit<ViewProps,"children"> {
  scope?:string;revision?:string|number;disabled?:boolean;
  /** Layers top to bottom (index 0 is the top), as in `LayerStack`. */
  layers:readonly ClipLayer[];
  /** The layer the switch acts on. */
  layerId:string;
  /** `setClipped`. */
  onSetClipped:(op:SetClippedOp,signal?:AbortSignal)=>void|Promise<unknown>;
  className?:string;
  unstyled?:boolean;
}

/**
 * Clip/unclip switch for one layer (B-13). Its label names the base it clips
 * to ("Clip to Photo"). On the bottom layer, or when every layer below is
 * already clipped, it stays visible and says why it cannot run.
 */
export function ClipToggle({scope="clipping",revision=0,disabled=false,layers,layerId,onSetClipped,className,unstyled=false,...rest}:ClipToggleProps){
  const layer=layers.find(l=>l.id===layerId);
  if(!layer)throw new RangeError("Unknown layer: "+layerId);
  if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid clipping identity');
  const blocked=clipReason(layers,layerId),boundary=JSON.stringify([scope,revision,disabled,layers,layerId]),action=useOwnedAction(boundary),pending=action.pending!==null,request=useRef<symbol|null>(null),committed=useRef<null|{boundary:string;onSetClipped:typeof onSetClipped}>(null);
  useLayoutEffect(()=>{committed.current={boundary,onSetClipped};});useLayoutEffect(()=>{request.current=null;},[boundary]);useLayoutEffect(()=>()=>{committed.current=null;},[]);
  const reason=disabled?'Clipping editing is disabled':pending?'Updating clipping':blocked;
  const toggle=()=>{const p=committed.current;if(!p||p.boundary!==boundary||reason||request.current)return;const token=Symbol();request.current=token;void action.run(layerId,signal=>p.onSetClipped({id:layerId,clipped:!layer.clipped},signal)).finally(()=>{if(request.current===token)request.current=null;});};
  const styled=!unstyled;
  const identity=JSON.stringify([scope,revision,disabled,layerId,layers.map(item=>[item.id,item.parent,item.parentId,item.locked,item.id===layerId?null:item.clipped])]);
  return <View key={identity} {...rest} {...{className:joinClasses("gap-1",className)}}>
    <PanelButton role="switch" label={clipToggleLabel(layers,layerId)} checked={layer.clipped} reason={reason}
      styled={styled} icon={<ClipGlyph styled={styled}/>}
      onPress={toggle}/>
    <Reason text={reason} styled={styled}/>
    <ErrorMessage {...(action.error?{message:action.error}:{})} unstyled={unstyled}/>
  </View>;
}

/** Props for {@linkcode ClipIndicator}. */
export interface ClipIndicatorProps extends Omit<ViewProps,"children"> {
  unstyled?:boolean;
}

/**
 * The 18pt indent and clip glyph at the start of a clipped layer's row, so the
 * row reads as hanging off the base below it. Decorative: the row's label
 * says "clipped to <base>". `LayerStack` draws it for rows with `clippedTo`.
 */
export function ClipIndicator({unstyled=false,style,...rest}:ClipIndicatorProps){
  return <View {...rest} pointerEvents="none" importantForAccessibility="no-hide-descendants" accessibilityElementsHidden
    {...{"aria-hidden":true}} style={[{width:CLIP_INDENT,alignSelf:"stretch",alignItems:"center",justifyContent:"center"},style]}>
    <ClipGlyph styled={!unstyled}/>
  </View>;
}

/**
 * A short down arrow: the layer hangs onto the one below it. Symmetric, so it
 * reads the same in left-to-right and right-to-left rows.
 */
function ClipGlyph({styled}:{styled:boolean}){
  const ink=joinClasses(styled&&"bg-text-muted");
  return <View pointerEvents="none" style={{width:12,height:16,alignItems:"center"}}>
    <View {...{className:ink}} style={{position:"absolute",top:1,width:1.5,height:13,borderRadius:1}}/>
    <View {...{className:ink}} style={{position:"absolute",top:10,left:1.6,width:6,height:1.5,borderRadius:1,transform:[{rotate:"45deg"}]}}/>
    <View {...{className:ink}} style={{position:"absolute",top:10,right:1.6,width:6,height:1.5,borderRadius:1,transform:[{rotate:"-45deg"}]}}/>
  </View>;
}

import type {ReactNode} from "react";
import {Pressable,Text,View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";

/**
 * Internal 44pt button shared by the layer panels. A control that cannot run
 * passes `reason`: it stays focusable and pressable (doing nothing), its name
 * ends in ", unavailable" and the reason is its hint, so a screen reader hears
 * why. Callers also print the reason next to the control (see {@linkcode Reason}).
 *
 * React Native Web's Pressable overwrites aria-disabled with its own `disabled`
 * prop, which would make the control unfocusable, so `disabled` is not used.
 */
export function PanelButton({label,onPress,reason,role="button",checked,tone="secondary",styled,icon,grow=false,testID}:{
  label:string;onPress:()=>void;reason?:string|undefined;role?:"button"|"switch";checked?:boolean;
  tone?:"primary"|"secondary"|"quiet";styled:boolean;icon?:ReactNode;grow?:boolean;testID?:string;
}){
  const off=reason!==undefined;
  const on=checked===true;
  const fill=tone==="primary"&&!off?"bg-primary border-primary":tone==="quiet"?"bg-transparent border-transparent":"bg-surface-raised border-border";
  const ink=tone==="primary"&&!off?"text-on-primary":"text-text";
  return <Pressable role={role} aria-label={off?label+", unavailable":label}
    aria-checked={role==="switch"?on:undefined} accessibilityState={{disabled:off,...(role==="switch"?{checked:on}:{})}}
    accessibilityHint={reason} testID={testID}
    onPress={()=>{if(!off)onPress();}}
    {...{className:joinClasses(styled&&"rounded-control border focus-visible:ring-2 focus-visible:ring-focus",styled&&fill)}}
    style={{minHeight:44,minWidth:44,paddingHorizontal:12,flexDirection:"row",alignItems:"center",justifyContent:"center",
      gap:8,opacity:off?0.45:1,...(grow?{flexGrow:1}:null)}}>
    {icon??null}
    <Text numberOfLines={1} {...{className:joinClasses(styled&&ink,styled&&"text-sm font-medium")}}>{label}</Text>
    {role==="switch"?<View pointerEvents="none"
      {...{className:joinClasses(styled&&(on?"bg-primary border-primary":"bg-surface-sunken border-border"))}}
      style={{width:30,height:18,borderRadius:9,borderWidth:1,justifyContent:"center",paddingHorizontal:2,
        alignItems:on?"flex-end":"flex-start"}}>
      <View {...{className:joinClasses(styled&&(on?"bg-on-primary":"bg-text-muted"))}} style={{width:12,height:12,borderRadius:6}}/>
    </View>:null}
  </Pressable>;
}

/** Visible reason line under a group of controls; renders nothing without a reason. */
export function Reason({text,styled}:{text:string|undefined;styled:boolean}){
  if(!text)return null;
  return <Text {...{className:joinClasses(styled&&"text-text-muted text-xs")}} style={{lineHeight:16}}>{text}</Text>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
